<section class="card"><div class="section-heading"><div><h2><?= e(t('Lecture calendar')) ?></h2><p class="muted"><?= e(t('Connect NIBM to keep lecture dates and planner reminders up to date.')) ?></p></div><a class="btn secondary" href="/uni/calendar"><?= e(t('Open lecture calendar →')) ?></a></div></section>
<?php $options=[
    ['view'=>'modules','type'=>'module','label'=>t('Modules & grades'),'detail'=>t('Subjects, credits and your grades.'),'count'=>count($modules),'unit'=>'modules'],
    ['view'=>'assignments','type'=>'assignment','label'=>t('Assignments'),'detail'=>t('Coursework, due dates and marks.'),'count'=>$pending,'unit'=>'pending'],
    ['view'=>'exams','type'=>'exam','label'=>t('Exams'),'detail'=>t('Exam dates, venues and results.'),'count'=>count($exams),'unit'=>'recorded'],
    ['view'=>'timetable','type'=>'class','label'=>t('Timetable'),'detail'=>t('Your recurring weekly classes.'),'count'=>count($timetable),'unit'=>'classes'],
]; ?>
<div class="uni-options-grid"><?php foreach($options as $option): ?><section class="card uni-option"><div class="section-heading"><h2><a href="/uni?view=<?= e($option['view']) ?>"><?= e($option['label']) ?></a></h2><span class="badge"><?= e($option['count']) ?> <?= e($option['unit']) ?></span></div><p class="muted"><?= e($option['detail']) ?></p><div class="hero-actions"><a class="btn secondary" href="/uni/add/<?= e($option['type']) ?>"><?= e(t('+ Add')) ?> <?= e($option['type']==='class' ? 'class' : $option['type']) ?></a><a href="/uni?view=<?= e($option['view']) ?>"><?= e(t('View all →')) ?></a></div></section><?php endforeach; ?></div>
<?php $overdue=array_filter($assignments,fn($item)=>$item['status']!=='done' && $item['due_date'] && $item['due_date']<ui_date('Y-m-d')); if($overdue): ?><section class="card"><h2><?= e(t('Assignments needing attention')) ?></h2><?php foreach(array_slice($overdue,0,5) as $item): ?><div class="simple-row"><div><strong><?= e($item['title']) ?></strong><small><?= e($item['module']) ?></small></div><span class="error-text"><?= e(t('Overdue ·')) ?> <?= e($item['due_date']) ?></span></div><?php endforeach; ?><p class="footnote"><a href="/uni?view=assignments"><?= e(t('Open assignments')) ?></a></p></section><?php endif; ?>
